package dev.algorithmlearning.api.courses.data;
import dev.algorithmlearning.api.courses.application.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class JpaCourseRepository implements CourseRepository { private final CourseCategoryJpaRepository categories; private final CourseLessonJpaRepository lessons; public JpaCourseRepository(CourseCategoryJpaRepository c,CourseLessonJpaRepository l){categories=c;lessons=l;} public CourseCategory saveCategory(CourseCategory c){return category(categories.save(new CourseCategoryEntity(c.id(),c.slug(),c.displayName(),c.sortOrder())));} public Optional<CourseCategory> findCategoryBySlug(String s){return categories.findBySlug(s).map(this::category);} public CourseLesson saveLesson(CourseLesson x){var c=categories.getReferenceById(x.category().id());return lesson(lessons.save(new CourseLessonEntity(x.id(),c,x.sourceIdentity(),x.sourceMarkdownPath(),x.englishTitle(),String.join("\u001f",x.tags()),x.detail(),x.sourceUrl(),x.sourceType(),x.sortOrder(),x.createdAt(),x.updatedAt())));} public Optional<CourseLesson> findLessonBySourceIdentity(String s){return lessons.findBySourceIdentity(s).map(this::lesson);} public Optional<CourseLesson> findLessonByIdentity(String s){return findLessonBySourceIdentity(s);} public List<CourseCategory> categories(){return categories.findAllByOrderBySortOrderAscSlugAsc().stream().map(this::category).toList();} public List<CourseLesson> lessons(String c,String tag,String q){var needle=q==null?"":q.toLowerCase();return lessons.findAllByOrderBySortOrderAscIdAsc().stream().map(this::lesson).filter(x->c==null||c.equals(x.category().slug())).filter(x->tag==null||x.tags().stream().anyMatch(t->t.equalsIgnoreCase(tag))).filter(x->needle.isBlank()||x.englishTitle().toLowerCase().contains(needle)||x.tags().stream().anyMatch(t->t.toLowerCase().contains(needle))).toList();} private CourseCategory category(CourseCategoryEntity e){return new CourseCategory(e.id,e.slug,e.displayName,e.sortOrder);} private CourseLesson lesson(CourseLessonEntity e){return new CourseLesson(e.id,category(e.category),e.sourceIdentity,e.sourceMarkdownPath,e.englishTitle,List.of(e.tags.split("\u001f")),e.detail,e.sourceUrl,e.sourceType,e.sortOrder,e.createdAt,e.updatedAt);} }
